struct MakerId(String); struct ApproverId(String);
struct Payment<State> { id: u64, state: State }
struct Pending { initiated_by: MakerId }
struct Approved { approved_by: ApproverId }

fn approve(p: Payment<Pending>, who: ApproverId) -> Result<Payment<Approved>, Error> {
    if who.0 == p.state.initiated_by.0 { return Err(Error::SelfApproval); }
    Ok(Payment { id: p.id, state: Approved { approved_by: who } })
}
fn release(p: Payment<Approved>) { /* only reachable from a consumed approval */ }
